using System;

public sealed class DataProcessor : IDisposable
{
    private SafeHandle _handle;
    private bool _disposed;

    public DataProcessor(SafeHandle handle)
    {
        _handle = handle ?? throw new ArgumentNullException(nameof(handle));
    }

    public void Process()
    {
        if (_disposed)
            throw new ObjectDisposedException(nameof(DataProcessor));
        // Use _handle here...
    }

    public void Dispose()
    {
        Dispose(disposing: true);
        GC.SuppressFinalization(this);
    }

    private void Dispose(bool disposing)
    {
        if (_disposed) return;

        if (disposing)
        {
            // Release managed resources
            _handle?.Dispose();
        }

        // Release unmanaged resources here
        _disposed = true;
    }

    ~DataProcessor() => Dispose(disposing: false);
}

